-- Canonical RSVP summaries and reviewed service quantities for shared experiences.
-- Requires shared-experience.sql and guest-rsvp.sql. No guest identities are copied.
begin;
create table if not exists public.cb_experience_targets(item_id uuid primary key references public.cb_experience_items on delete cascade,basis text not null check(basis in ('Confirmed','Invited')),per_guest numeric not null check(per_guest between 0 and 100),reserve_percent numeric not null check(reserve_percent between 0 and 100),enabled boolean not null,revision bigint not null default 1,reviewed_counts jsonb not null,updated_at timestamptz not null default now());
create table if not exists public.cb_experience_target_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_experience_target_history(item_id uuid not null references public.cb_experience_items on delete cascade,revision bigint not null,actor_id uuid not null references auth.users,snapshot jsonb not null,at timestamptz not null default now(),primary key(item_id,revision));
alter table public.cb_experience_targets enable row level security;alter table public.cb_experience_target_writes enable row level security;alter table public.cb_experience_target_history enable row level security;
revoke all on public.cb_experience_targets,public.cb_experience_target_writes,public.cb_experience_target_history from public,anon,authenticated;
create or replace function public.cb_experience_guest_counts(p_event uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare ev public.cb_project_events;result jsonb;begin
 select * into ev from public.cb_project_events where id=p_event;
 if ev.id is null or not coalesce(public.cb_project_access(ev.project_id,'write') and public.cb_experience_member(ev.id,auth.uid()),false) then raise exception 'Guest management and celebration access required' using errcode='42501';end if;
 with people as (
 select coalesce(a->>'status','Pending') status,btrim(coalesce(a->>'meal','')) meal,btrim(coalesce(a->>'diet','')) diet,btrim(coalesce(a->>'access','')) access_note from public.cb_rsvp_households h cross join lateral jsonb_array_elements(h.data->'members') m left join lateral (select value a from jsonb_array_elements(h.answers) where value->>'guest'=m->>'id' and value->>'event'=p_event::text limit 1) answer on true where h.project_id=ev.project_id and m->'events' ? p_event::text
 ) select jsonb_build_object('invited',count(*),'confirmed',count(*) filter(where status='Confirmed'),'declined',count(*) filter(where status='Declined'),'pending',count(*) filter(where status not in ('Confirmed','Declined')),'dietary_notes',count(*) filter(where status='Confirmed' and diet<>''),'accessibility_notes',count(*) filter(where status='Confirmed' and access_note<>''),'meal_unspecified',count(*) filter(where status='Confirmed' and meal=''),'meals',(select coalesce(jsonb_agg(jsonb_build_object('meal',meal,'count',n) order by meal),'[]') from (select meal,count(*) n from people where status='Confirmed' and meal<>'' group by meal) meal_groups)) into result from people;
 return result||jsonb_build_object('hash',md5(result::text));end;$$;
create or replace function public.cb_experience_service_plan(p_event uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare counts jsonb;ev public.cb_project_events;begin
 counts=public.cb_experience_guest_counts(p_event);select * into ev from public.cb_project_events where id=p_event;
 return jsonb_build_object('event',ev.id,'event_revision',ev.revision,'counts',counts,'as_of',now(),'items',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'revision',i.revision,'title',i.data->>'title','section',i.data->>'section','unit',i.data->>'unit','quantity',i.data->'quantity','status',i.data->>'status','settings',case when t.item_id is null then null else jsonb_build_object('revision',t.revision,'basis',t.basis,'per_guest',t.per_guest,'reserve_percent',t.reserve_percent,'enabled',t.enabled,'reviewed_counts',t.reviewed_counts) end,'target',case when t.enabled then ceil((counts->>(case when t.basis='Confirmed' then 'confirmed' else 'invited' end))::numeric*t.per_guest*(1+t.reserve_percent/100)) else null end,'shortfall',case when t.enabled then greatest(0,ceil((counts->>(case when t.basis='Confirmed' then 'confirmed' else 'invited' end))::numeric*t.per_guest*(1+t.reserve_percent/100))-(i.data->>'quantity')::numeric) else null end,'counts_changed',t.item_id is not null and t.reviewed_counts->>'hash' is distinct from counts->>'hash') order by i.data->>'section',i.data->>'title',i.id),'[]') from public.cb_experience_items i left join public.cb_experience_targets t on t.item_id=i.id where i.event_id=p_event and i.data->>'section' in ('food','drinks','cake','hospitality') and i.data->>'status'<>'Cancelled'));
end;$$;
create or replace function public.cb_save_experience_target(p_event uuid,p_event_revision bigint,p_item uuid,p_item_revision bigint,p_revision bigint,p_client uuid,p_counts_hash text,p_basis text,p_per_guest numeric,p_reserve numeric,p_enabled boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare ev public.cb_project_events;i public.cb_experience_items;t public.cb_experience_targets;w public.cb_experience_target_writes;counts jsonb;payload jsonb;result jsonb;begin
 select * into ev from public.cb_project_events where id=p_event;perform 1 from public.cb_projects where id=ev.project_id for update;
 select * into ev from public.cb_project_events where id=p_event for update;
 if ev.id is null or not coalesce(public.cb_project_access(ev.project_id,'write') and public.cb_experience_member(ev.id,auth.uid()),false) then raise exception 'Guest management and celebration access required' using errcode='42501';end if;
 payload=jsonb_build_object('event',p_event,'event_revision',p_event_revision,'item',p_item,'item_revision',p_item_revision,'revision',p_revision,'counts_hash',p_counts_hash,'basis',p_basis,'per_guest',p_per_guest,'reserve',p_reserve,'enabled',p_enabled);
 if p_client is null then raise exception 'Request ID required';end if;select * into w from public.cb_experience_target_writes where user_id=auth.uid() and client=p_client;if found then if w.payload is distinct from payload then raise exception 'Retry the original service target' using errcode='PT409';end if;return w.response;end if;
 if ev.revision is distinct from p_event_revision then raise exception 'The celebration changed. Refresh the service plan before saving.' using errcode='PT409';end if;
 select * into i from public.cb_experience_items where id=p_item and event_id=p_event for update;
 if i.id is null or i.data->>'section' not in ('food','drinks','cake','hospitality') or i.data->>'status'='Cancelled' then raise exception 'Choose an active food, drinks, cake or hospitality item';end if;
 if i.revision is distinct from p_item_revision then raise exception 'The service item changed. Refresh before reviewing its target.' using errcode='PT409';end if;
 counts=public.cb_experience_guest_counts(p_event);if counts->>'hash' is distinct from p_counts_hash then raise exception 'Guest responses changed. Refresh and review the new totals before saving.' using errcode='PT409';end if;
 if p_basis is null or p_basis not in ('Confirmed','Invited') or p_per_guest is null or p_per_guest not between 0 and 100 or p_reserve is null or p_reserve not between 0 and 100 or p_enabled is null then raise exception 'Choose a guest basis and values between zero and 100';end if;
 if p_per_guest::text in ('NaN','Infinity','-Infinity') or p_reserve::text in ('NaN','Infinity','-Infinity') then raise exception 'Use finite service quantities';end if;
 select * into t from public.cb_experience_targets where item_id=p_item for update;if coalesce(t.revision,0) is distinct from p_revision then raise exception 'Another teammate changed this service target. Refresh first.' using errcode='PT409';end if;
 insert into public.cb_experience_targets(item_id,basis,per_guest,reserve_percent,enabled,reviewed_counts) values(p_item,p_basis,p_per_guest,p_reserve,p_enabled,counts-'meals') on conflict(item_id) do update set basis=excluded.basis,per_guest=excluded.per_guest,reserve_percent=excluded.reserve_percent,enabled=excluded.enabled,reviewed_counts=excluded.reviewed_counts,revision=public.cb_experience_targets.revision+1,updated_at=now() returning * into t;
 insert into public.cb_experience_target_history values(t.item_id,t.revision,auth.uid(),to_jsonb(t),now());result=jsonb_build_object('saved',true,'revision',t.revision);insert into public.cb_experience_target_writes values(auth.uid(),p_client,payload,result);return result;
end;$$;
revoke all on function public.cb_experience_guest_counts(uuid),public.cb_experience_service_plan(uuid),public.cb_save_experience_target(uuid,bigint,uuid,bigint,bigint,uuid,text,text,numeric,numeric,boolean) from public,anon,authenticated;
grant execute on function public.cb_experience_service_plan(uuid),public.cb_save_experience_target(uuid,bigint,uuid,bigint,bigint,uuid,text,text,numeric,numeric,boolean) to authenticated;
notify pgrst,'reload schema';commit;
